package io.github.gambitly.data

import android.content.Context
import androidx.room.Dao
import androidx.room.Database
import androidx.room.Entity
import androidx.room.PrimaryKey
import androidx.room.Query
import androidx.room.Room
import androidx.room.RoomDatabase

// Read-only content shipped as assets/content.db, generated by tools/build_content.py.
// Table layouts here must match the SCHEMA in that script.

@Entity(tableName = "openings")
data class Opening(
    @PrimaryKey val id: Int,
    val eco: String,
    val name: String,
    /** The part of the name before the colon, e.g. "Sicilian Defense". */
    val family: String,
    /** Space-separated SAN moves. */
    val moves: String,
    val plies: Int,
) {
    val sanMoves: List<String> get() = moves.split(' ')

    /** The name without its family prefix, or "Main line" when there is none. */
    val variation: String get() = name.substringAfter(": ", "").ifEmpty { "Main line" }
}

@Entity(tableName = "puzzles")
data class Puzzle(
    @PrimaryKey val id: String,
    /** Position before the opponent's set-up move. */
    val fen: String,
    /** Space-separated UCI moves; the first is the opponent's set-up move, then the solution alternates. */
    val moves: String,
    val rating: Int,
    /** Space-padded Lichess theme keys, e.g. " fork middlegame short ". */
    val themes: String,
) {
    val uciMoves: List<String> get() = moves.split(' ')
    val themeList: List<String> get() = themes.trim().split(' ')
}

@Entity(tableName = "classics")
data class Classic(
    @PrimaryKey val id: Int,
    val title: String,
    val white: String,
    val black: String,
    val event: String,
    val year: Int,
    val result: String,
    /** "w" or "b": the side whose moves the user guesses by default. */
    val hero: String,
    val intro: String,
    /** Space-separated SAN moves. */
    val moves: String,
) {
    val sanMoves: List<String> get() = moves.split(' ')
}

@Entity(tableName = "endgames")
data class Endgame(
    @PrimaryKey val id: Int,
    val category: String,
    val title: String,
    val fen: String,
    /** "w" or "b". */
    val userSide: String,
    /** "mate", "promote" or "draw". */
    val goal: String,
    /** Number of the user's own moves allowed to reach the goal (or to hold, for "draw"). */
    val moveLimit: Int,
    val hint: String,
)

data class FamilyCount(val family: String, val lines: Int)

@Dao
interface ContentDao {
    @Query("SELECT family, COUNT(*) AS lines FROM openings GROUP BY family ORDER BY family")
    suspend fun openingFamilies(): List<FamilyCount>

    @Query("SELECT * FROM openings WHERE family = :family ORDER BY plies, name")
    suspend fun openingsInFamily(family: String): List<Opening>

    @Query("SELECT * FROM openings WHERE name LIKE '%' || :query || '%' OR eco LIKE :query || '%' ORDER BY plies, name LIMIT 200")
    suspend fun searchOpenings(query: String): List<Opening>

    @Query("SELECT * FROM openings WHERE id = :id")
    suspend fun opening(id: Int): Opening?

    /** A random puzzle in the rating window, optionally limited to one theme ('' for any). */
    @Query(
        "SELECT * FROM puzzles WHERE (:theme = '' OR themes LIKE '% ' || :theme || ' %') " +
            "AND rating BETWEEN :minRating AND :maxRating AND id != :excludeId ORDER BY RANDOM() LIMIT 1",
    )
    suspend fun randomPuzzle(theme: String, minRating: Int, maxRating: Int, excludeId: String): Puzzle?

    @Query("SELECT * FROM classics ORDER BY year, id")
    suspend fun classics(): List<Classic>

    @Query("SELECT * FROM classics WHERE id = :id")
    suspend fun classic(id: Int): Classic?

    @Query("SELECT * FROM endgames ORDER BY id")
    suspend fun endgames(): List<Endgame>

    @Query("SELECT * FROM endgames WHERE id = :id")
    suspend fun endgame(id: Int): Endgame?
}

@Database(
    entities = [Opening::class, Puzzle::class, Classic::class, Endgame::class],
    version = 1, // keep in step with DB_VERSION in tools/build_content.py
    exportSchema = false,
)
abstract class ContentDatabase : RoomDatabase() {
    abstract fun dao(): ContentDao

    companion object {
        fun open(context: Context): ContentDatabase =
            Room.databaseBuilder(context, ContentDatabase::class.java, "content.db")
                .createFromAsset("content.db")
                // Content is read-only, so a new version simply replaces the old copy.
                .fallbackToDestructiveMigration(dropAllTables = true)
                .build()
    }
}
